using System.Buffers.Binary;
using System.Text.Json;
using System.Text.Json.Nodes;
using Stardust.Core.Protocol;
namespace Stardust.Core.SmokeTests;
public static class CreatureDefendersView6Scenarios
{
 private static object Row(CreatureDefendersView6State s)=>new{s.ObjectId,s.Revision,Defenders=new{s.Defenders.Counter,Values=s.Defenders.Values.ToArray()},s.DecodedBytes};
 private static object Plan(CreatureDefendersView6Delta p)=>new{p.ObjectId,p.DeclaredCount,Updates=p.Updates.Select(u=>new{u.Field,u.Extent,u.Counter,Commands=u.Commands.Select(c=>new{c.Opcode,c.Index,Values=c.Values.ToArray()}).ToArray()}).ToArray()};
 private static object Events(CreatureDefendersView6Change c)=>c.Events.Select(e=>new{e.Field,e.Opcode,Kind=e.Kind.ToString(),e.Index,e.OldId,e.NewId}).ToArray();
 public static void Run(string input,string output)
 {
  if(new FileInfo(input).Length>4194304)throw new InvalidDataException("Bounded defender fixture");using var doc=JsonDocument.Parse(File.ReadAllBytes(input));var records=new List<object>();int negatives=0,budgets=0,ownership=0;var codec=new CreatureDefendersView6Limits();var positive=new CreatureDefendersView6StateLimits(MaximumElements:65536);
  void Check(bool v,string why){if(!v)throw new Exception(why);}
  void Equal(object v,JsonElement expected,string why)=>Check(JsonNode.DeepEquals(JsonSerializer.SerializeToNode(v),JsonNode.Parse(expected.GetRawText())),why);
  void Reject(Action a){negatives++;try{a();}catch(InvalidDataException){return;}catch(ArgumentException){return;}catch(OverflowException){return;}throw new Exception("Negative defender accepted");}
  foreach(var c in doc.RootElement.GetProperty("Cases").EnumerateArray())
  {
   var wire=Convert.FromHexString(c.GetProperty("Hex").GetString()!);var seedWire=Convert.FromHexString(c.GetProperty("Baseline").GetString()!);var baseline=CreatureView6Codec.DecodeBaseline(seedWire,new());var p=CreatureDefendersView6Codec.Decode(wire,codec);Equal(Plan(p),c.GetProperty("Plan"),"Independent defender plan");Check(CreatureDefendersView6Codec.Encode(p,codec).SequenceEqual(wire),"Exact defender bytes");var envelope=ReplicationEnvelopeCodec.DecodeDelta(wire,codec.MaximumPayloadBytes);Equal(Plan(CreatureDefendersView6Codec.Decode(envelope,codec)),c.GetProperty("Plan"),"Envelope decode");Check(CreatureDefendersView6Codec.EncodeEnvelope(p,codec).CopyOpaqueFields().SequenceEqual(envelope.CopyOpaqueFields()),"Envelope encode");
   var state=CreatureDefendersView6State.FromBaseline(baseline);Equal(Row(state),c.GetProperty("Initial"),"Seed projection");var old=JsonSerializer.Serialize(Row(state));var change=state.Apply(p,positive);Equal(Row(change.Current),c.GetProperty("Expected"),"Independent complete defender values");Equal(Events(change),c.GetProperty("Events"),"Modern ordered events");Check(change.WorkUsed==c.GetProperty("Work").GetInt64(),"Independent work");Check(change.DeclaredCount==p.DeclaredCount&&change.Current.Revision==2,"Single revision/raw metadata");Check(change.DecodedOutputBytes==change.Current.DecodedBytes+32L*change.Events.Count,"Output charge");Check(JsonSerializer.Serialize(Row(state))==old,"Input immutable");ownership++;
   Check(CreatureView6Codec.EncodeBaseline(baseline,new()).SequenceEqual(seedWire),"Complete seed untouched");ownership++;
   var alias=(byte[])wire.Clone();var owned=CreatureDefendersView6Codec.Decode(alias,codec);Array.Clear(alias);Check(CreatureDefendersView6Codec.Encode(owned,codec).SequenceEqual(wire),"Wire ownership");ownership++;
   var firstCommand=p.Updates.SelectMany(u=>u.Commands).FirstOrDefault();if(firstCommand is not null){var inputValues=firstCommand.Values.ToArray();var copied=new CreatureDefendersView6Command(firstCommand.Opcode,firstCommand.Index,inputValues);Array.Clear(inputValues);Check(JsonSerializer.Serialize(copied.Values)==JsonSerializer.Serialize(firstCommand.Values),"Command owns value array");ownership++;}var updateCommands=p.Updates[0].Commands.ToArray();var copiedUpdate=new CreatureDefendersView6Update(1,p.Updates[0].Extent,p.Updates[0].Counter,updateCommands);Array.Clear(updateCommands);Check(copiedUpdate.Commands.Count==p.Updates[0].Commands.Count,"Update owns command array");ownership++;var list=p.Updates.ToArray();var frozen=new CreatureDefendersView6Delta(p.ObjectId,p.DeclaredCount,list);Array.Clear(list);Check(CreatureDefendersView6Codec.Encode(frozen,codec).SequenceEqual(wire),"Plan freezes list");ownership++;
   var inspected=change.Current.Defenders.Values.ToArray();Array.Clear(inspected);Equal(Row(change.Current),c.GetProperty("Expected"),"Inspection ownership");ownership++;
   Equal(Row(Task.Run(()=>state.Apply(p,positive)).GetAwaiter().GetResult().Current),c.GetProperty("Expected"),"Immutable branch");ownership++;
   var cc=c.GetProperty("CodecCost");int CN(string k)=>cc.GetProperty(k).GetInt32();long CL(string k)=>cc.GetProperty(k).GetInt64();var exact=new CreatureDefendersView6Limits(CN("Payload"),CN("Fields"),CN("Commands"),CN("Values"),CL("Decoded"),CL("Work"));_=CreatureDefendersView6Codec.Decode(wire,exact);Check(CreatureDefendersView6Codec.Encode(p,exact).SequenceEqual(wire),"Exact codec caps");budgets+=2;
   var less=new List<CreatureDefendersView6Limits>{exact with{MaximumPayloadBytes=exact.MaximumPayloadBytes-1},exact with{MaximumFields=exact.MaximumFields-1},exact with{MaximumDecodedBytes=exact.MaximumDecodedBytes-1},exact with{MaximumWork=exact.MaximumWork-1}};if(exact.MaximumCommands>0)less.Add(exact with{MaximumCommands=exact.MaximumCommands-1});if(exact.MaximumValues>0)less.Add(exact with{MaximumValues=exact.MaximumValues-1});foreach(var l in less){Reject(()=>CreatureDefendersView6Codec.Decode(wire,l));Reject(()=>CreatureDefendersView6Codec.Encode(p,l));budgets+=2;}
   var sc=c.GetProperty("StateCost");int SN(string k)=>sc.GetProperty(k).GetInt32();long SL(string k)=>sc.GetProperty(k).GetInt64();var sm=new CreatureDefendersView6StateLimits(SN("Elements"),SL("StateBytes"),SN("Events"),SL("OutputBytes"),SL("Work"),exact);Equal(Row(state.Apply(p,sm).Current),c.GetProperty("Expected"),"Exact intermediate state caps");budgets++;
   var sless=new List<CreatureDefendersView6StateLimits>{sm with{MaximumStateBytes=sm.MaximumStateBytes-1},sm with{MaximumOutputBytes=sm.MaximumOutputBytes-1},sm with{MaximumWork=sm.MaximumWork-1}};if(sm.MaximumElements>0)sless.Add(sm with{MaximumElements=sm.MaximumElements-1});if(sm.MaximumEvents>0)sless.Add(sm with{MaximumEvents=sm.MaximumEvents-1});foreach(var l in sless){Reject(()=>state.Apply(p,l));Check(JsonSerializer.Serialize(Row(state))==old,"Failed state preserves input");budgets++;}foreach(var l in less){Reject(()=>state.Apply(p,sm with{MessageLimits=l}));budgets++;}
   var seedLimits=new CreatureDefendersView6StateLimits(state.Defenders.Values.Count,state.DecodedBytes,0,state.DecodedBytes,state.Defenders.Values.Count);_=CreatureDefendersView6State.FromBaseline(baseline,seedLimits);budgets++;if(seedLimits.MaximumWork>0){Reject(()=>CreatureDefendersView6State.FromBaseline(baseline,seedLimits with{MaximumWork=seedLimits.MaximumWork-1}));budgets++;}var reseed=change.Current.Reseed(baseline);Equal(Row(reseed),c.GetProperty("Reseed"),"Reseed");Reject(()=>state.Apply(new(p.ObjectId+1,0,p.Updates)));var wrong=(byte[])seedWire.Clone();BinaryPrimitives.WriteUInt64LittleEndian(wrong.AsSpan(6),p.ObjectId+1);Reject(()=>state.Reseed(CreatureView6Codec.DecodeBaseline(wrong,new())));Reject(()=>CreatureDefendersView6State.FromBaseline(baseline,null,ulong.MaxValue));var end=CreatureDefendersView6State.FromBaseline(baseline,null,ulong.MaxValue-1);Reject(()=>end.Apply(p));Reject(()=>end.Reseed(baseline));
   var valid=c.GetProperty("ValidPrefixes").EnumerateArray().Select(x=>x.GetInt32()).ToHashSet();for(int n=0;n<wire.Length;n++){var truncated=wire[..n];Reject(()=>CreatureDefendersView6Codec.Decode(truncated,codec));if(n>=25){BinaryPrimitives.WriteUInt32LittleEndian(truncated.AsSpan(19),(uint)(n-23));try{var partial=CreatureDefendersView6Codec.Decode(truncated,codec);Check(valid.Contains(n),"Independent valid prefix set");Check(CreatureDefendersView6Codec.Encode(partial,codec).SequenceEqual(truncated),"Exact complete prefix");}catch(InvalidDataException){Check(!valid.Contains(n),"Complete prefix rejected");negatives++;}}}
   string kept=JsonSerializer.Serialize(Row(change.Current));Reject(()=>change.Current.Apply(p,sm with{MaximumWork=0}));Check(JsonSerializer.Serialize(Row(change.Current))==kept,"Earlier result survives later failure");ownership++;
   records.Add(new{Name=c.GetProperty("Name").GetString(),Plan=Plan(p),Initial=Row(state),Expected=Row(change.Current),Events=Events(change),Work=change.WorkUsed,Reseed=Row(reseed)});
  }
  foreach(var m in doc.RootElement.GetProperty("Malformed").EnumerateArray())Reject(()=>CreatureDefendersView6Codec.Decode(Convert.FromHexString(m.GetString()!),codec));Reject(()=>CreatureDefendersView6Codec.Encode(new(1,0,[]),codec));Reject(()=>CreatureDefendersView6Codec.Encode(new(1,0,[new(1,0,0,[new(4,0,[])])]),codec));Reject(()=>CreatureDefendersView6Codec.Encode(new(1,0,[new(1,1,0,[])]),codec));Reject(()=>new CreatureDefendersView6Command(5,0,[]));Reject(()=>new CreatureDefendersView6Command(1,0,[]));Reject(()=>new CreatureDefendersView6Command(3,1,[]));Reject(()=>new CreatureDefendersView6Command(3,0,Enumerable.Repeat(0UL,65536)));
  foreach(ushort field in new ushort[]{0,2,15,65535})Reject(()=>new CreatureDefendersView6Update(field,0,0,[]));
  File.WriteAllText(output,JsonSerializer.Serialize(new{Records=records,Negatives=negatives,Budgets=budgets,Ownership=ownership},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine($"PASS defender {records.Count} cases, {negatives} negatives, {budgets} budgets, {ownership} ownership checks");
 }
}
